<template>
  <view class="page">
    <view class="topbar"><view class="back" @click="goBack">‹</view><view><text class="title">校园组团</text><text class="subtitle">找搭子，一起做有趣的事</text></view><view class="my-link" @click="selectMode('joined')">我的参与</view></view>

    <view class="hero">
      <view><text class="hero-tag">CAMPUS TOGETHER</text><text class="hero-title">今天想找谁一起？</text><text class="hero-copy">自习、电影、聚餐、拼车、运动，都能发起组团</text></view>
      <view class="hero-art"><text>团</text><view /></view>
    </view>

    <scroll-view class="category-scroll" scroll-x :show-scrollbar="false"><view class="category-row"><view :class="['category', { active: !activeCategory }]" @click="selectCategory('')"><i />全部</view><view v-for="(item,index) in categories" :key="item.code" :class="['category', { active: activeCategory === item.code }]" :style="categoryStyle(item,index)" @click="selectCategory(item.code)"><i />{{ item.label }}</view></view></scroll-view>

    <view class="mode-grid"><view :class="{ active: mode === 'all' }" @click="selectMode('all')">发现组团</view><view :class="{ active: mode === 'created' }" @click="selectMode('created')">我发起的</view><view :class="{ active: mode === 'joined' }" @click="selectMode('joined')">我的参与</view></view>

    <view class="list-head"><view><text>{{ modeTitle }}</text><text>{{ mode === 'all' ? '看看同学们最近在计划什么' : '管理你的校园组团' }}</text></view><button :disabled="loading" @click="createActivity">＋ 发起组团</button></view>

    <view v-if="loading" class="loading-list"><view v-for="index in 3" :key="index" class="activity-card tm-skeleton" /></view>
    <view v-else-if="error" class="state-card error"><view class="state-icon">!</view><text class="state-title">组团加载失败</text><text class="state-copy">{{ error }}</text><button @click="load">重新加载</button></view>
    <template v-else>
      <view v-for="(activity,index) in activities" :key="activity.id" class="activity-card" @click="openDetail(activity.id)">
        <view class="activity-accent" :style="{ background: accentColor(activity.category_code,index) }" />
        <image v-if="firstImage(activity)" class="activity-image" :src="firstImage(activity)" mode="aspectFill" />
        <view v-else class="activity-image fallback" :style="{ background: accentColor(activity.category_code,index) }"><text>{{ activity.category_label.slice(0,1) }}</text></view>
        <view class="activity-main"><view class="activity-head"><text class="category-tag">{{ activity.category_label }}</text><text :class="['status', `status-${statusTone(activity.status)}`]">{{ statusText(activity.status) }}</text></view><text class="activity-title">{{ activity.title }}</text><text class="activity-details">{{ activity.details }}</text><view class="meta"><text>◷ {{ formatStart(activity.starts_at) }}</text><text>⌖ {{ activity.location || '校内地点待定' }}</text></view><view class="activity-foot"><view class="creator"><view>{{ avatarText(activity.creator.nickname) }}</view><text>{{ activity.creator.nickname }}</text></view><view class="capacity"><strong>{{ activity.participant_count }}</strong>/{{ activity.participant_limit }} 人 <text>›</text></view></view></view>
      </view>
      <view v-if="!activities.length" class="state-card"><view class="state-icon">团</view><text class="state-title">暂时还没有这样的组团</text><text class="state-copy">发起第一个活动，邀请同学一起自习、运动或探索校园。</text><button @click="createActivity">发起组团</button></view>
    </template>

    <view class="safe-space" />
    <button class="floating-create" :disabled="loading" @click="createActivity"><text>＋</text> 发起组团</button>
    <AppTabBar current-target="community" @compose="createActivity" />
  </view>
</template>

<script setup lang="ts">
import { computed, ref } from 'vue'
import { onLoad, onPullDownRefresh, onShow } from '@dcloudio/uni-app'
import { communityActivityImageUrl, listCommunityActivities, listCommunityActivityCategories, listMyCommunityActivities, type CommunityActivity, type CommunityActivityCategory } from '@/api/community'
import AppTabBar from '@/components/AppTabBar.vue'
import { useAuthStore } from '@/stores/auth'
import { navigateToLogin } from '@/utils/authRedirect'

type Mode = 'all' | 'created' | 'joined'
const fallbackCategories: CommunityActivityCategory[] = [
  { code:'study',label:'自习' },{ code:'movie',label:'电影' },{ code:'dining',label:'聚餐' },{ code:'carpool',label:'拼车' },
  { code:'group_buy',label:'拼单' },{ code:'gaming',label:'游戏' },{ code:'sports',label:'运动' },{ code:'travel',label:'旅行' },{ code:'other',label:'其他' },
]
const auth = useAuthStore()
const categories = ref<CommunityActivityCategory[]>(fallbackCategories)
const activities = ref<CommunityActivity[]>([])
const activeCategory = ref('')
const mode = ref<Mode>('all')
const loading = ref(false)
const error = ref('')
const modeTitle = computed(() => ({ all:'最新组团',created:'我发起的组团',joined:'我参与的组团' })[mode.value])

onLoad((options?:Record<string,string|undefined>) => { activeCategory.value = options?.category || '' })
onShow(async () => { await Promise.all([loadCategories(),load()]) })
onPullDownRefresh(async () => { try { await load() } finally { uni.stopPullDownRefresh() } })

async function loadCategories(){ try { const result=await listCommunityActivityCategories(); categories.value=result.items.length?result.items:fallbackCategories } catch { categories.value=fallbackCategories } }
async function load(){ loading.value=true; error.value=''; try { if(mode.value==='all'){ const result=await listCommunityActivities({category:activeCategory.value||undefined,page_size:30},auth.accessToken||undefined); activities.value=result.items } else { if(!ensureAuth()) return; const result=await listMyCommunityActivities(auth.accessToken,mode.value); activities.value=activeCategory.value?result.items.filter(item=>item.category_code===activeCategory.value):result.items } } catch(cause){ error.value=message(cause) } finally { loading.value=false } }
async function selectCategory(value:string){ activeCategory.value=value; await load() }
async function selectMode(value:Mode){ if(value!=='all'&&!ensureAuth())return; mode.value=value; await load() }
function ensureAuth(){ if(auth.accessToken)return true; uni.showModal({title:'登录后查看组团',content:'登录后可以发起、报名和管理校园组团。',confirmText:'去登录',success:result=>{if(result.confirm)navigateToLogin()}}); return false }
function createActivity(){ if(!ensureAuth())return; uni.navigateTo({url:'/pages/community-activity-compose/index'}) }
function openDetail(id:string){ uni.navigateTo({url:`/pages/community-activity-detail/index?id=${encodeURIComponent(id)}`}) }
function goBack(){ const pages=getCurrentPages(); pages.length>1?uni.navigateBack():uni.reLaunch({url:'/pages/community/index'}) }
function categoryStyle(item:CommunityActivityCategory,index:number){ return {'--category-color':item.color||['#39c8ff','#ff6f9b','#ff9847','#ba8355','#ff5e71','#a35cff','#62d84d','#16cca2','#717985'][index%9]} }
function accentColor(code:string,index:number){ const item=categories.value.find(entry=>entry.code===code); return item?.color||['#39c8ff','#ff6f9b','#ff9847','#ba8355','#ff5e71','#a35cff','#62d84d','#16cca2','#717985'][Math.max(0,categories.value.findIndex(entry=>entry.code===code))%9]||['#39c8ff','#ff6f9b','#ff9847'][index%3] }
function firstImage(activity:CommunityActivity){ const image=activity.images?.[0]; return image?communityActivityImageUrl(image):'' }
function avatarText(value:string){ return (value||'同').slice(0,1) }
function statusText(value:string){ return ({pending_review:'审核中',approved:'报名中',closed:'已关闭',rejected:'未通过'} as Record<string,string>)[value]||'处理中' }
function statusTone(value:string){ return ({approved:'open',pending_review:'pending',rejected:'danger',closed:'muted'} as Record<string,string>)[value]||'pending' }
function formatStart(value:string){ const date=new Date(value); if(Number.isNaN(date.getTime()))return value; return `${date.getMonth()+1}月${date.getDate()}日 ${String(date.getHours()).padStart(2,'0')}:${String(date.getMinutes()).padStart(2,'0')}` }
function message(value:unknown){ return value instanceof Error?value.message:'请检查网络后重试' }
</script>

<style scoped>
