position:absolute;right:0;bottom:0;width:74rpx;height:74rpx;border:3rpx solid var(--ink);border-radius:50%;background:#52d7ff}.category-scroll{margin:31rpx -24rpx 0;padding:0 24rpx;box-sizing:border-box;white-space:nowrap}.category-row{gap:13rpx;padding:8rpx 28rpx 9rpx 0}.category{display:flex;align-items:center;gap:9rpx;padding:14rpx 20rpx;border:2rpx solid var(--ink);border-radius:14rpx;background:#fff;box-shadow:0 5rpx 0 rgba(17,24,39,.16);font-size:19rpx;font-weight:900}.category i{display:block;width:8rpx;height:34rpx;border-radius:999rpx;background:var(--category-color,#111827)}.category.active{background:var(--ink);color:#fff;box-shadow:0 5rpx 0 #ff5c70}.mode-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8rpx;margin-top:19rpx;padding:7rpx;border:2rpx solid var(--ink);border-radius:18rpx;background:#fff}.mode-grid view{padding:14rpx 6rpx;text-align:center;border-radius:12rpx;font-size:18rpx;font-weight:850}.mode-grid view.active{background:#111827;color:#fff}.list-head{justify-content:space-between;margin:28rpx 4rpx 6rpx}.list-head>view text:first-child{font-size:28rpx;font-weight:950}.list-head>view text:last-child{margin-top:4rpx;color:#767e8c;font-size:16rpx}.list-head button{width:auto;height:58rpx;margin:0;padding:0 17rpx;border:2rpx solid var(--ink);border-radius:999rpx;background:#26df9e;font-size:17rpx;font-weight:950;line-height:54rpx;box-shadow:0 4rpx 0 var(--ink)}.list-head button::after,.state-card button::after,.floating-create::after{border:0}.activity-card{position:relative;align-items:stretch;overflow:hidden;margin-top:16rpx;border:3rpx solid var(--ink);border-radius:23rpx;background:#fff;box-shadow:0 8rpx 0 rgba(17,24,39,.12)}.activity-accent{position:absolute;left:0;top:0;bottom:0;width:10rpx}.activity-image{width:180rpx;min-height:235rpx;flex:none;border-right:3rpx solid var(--ink)}.activity-image.fallback{display:flex;align-items:center;justify-content:center}.activity-image.fallback text{display:flex;align-items:center;justify-content:center;width:88rpx;height:88rpx;border:3rpx solid var(--ink);border-radius:28rpx;background:rgba(255,255,255,.74);font-size:37rpx;font-weight:950}.activity-main{min-width:0;flex:1;padding:19rpx}.activity-head{justify-content:space-between;gap:10rpx}.category-tag,.status{padding:5rpx 10rpx;border-radius:999rpx;font-size:14rpx;font-weight:900}.category-tag{background:#edf0f3}.status-open{background:#cff8e7;color:#087a53}.status-full{background:#ffe1a7;color:#8d5800}.status-pending{background:#dcedff;color:#175b9c}.status-danger{background:#ffe0e5;color:#b7293d}.status-muted{background:#eceef1;color:#6b7380}.activity-title{overflow:hidden;margin-top:11rpx;font-size:24rpx;font-weight:950;text-overflow:ellipsis;white-space:nowrap}.activity-details{display:-webkit-box;overflow:hidden;margin-top:6rpx;color:#5d6675;font-size:17rpx;line-height:1.45;-webkit-box-orient:vertical;-webkit-line-clamp:2}.meta{gap:13rpx;margin-top:11rpx;color:#777f8c;font-size:15rpx}.meta text{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.activity-foot{justify-content:space-between;margin-top:15rpx;padding-top:12rpx;border-top:1rpx dashed #d7dce2}.creator{gap:7rpx;min-width:0}.creator view{display:flex;align-items:center;justify-content:center;width:34rpx;height:34rpx;border:2rpx solid var(--ink);border-radius:50%;background:#ffcc73;font-size:14rpx;font-weight:900}.creator text{overflow:hidden;max-width:100rpx;font-size:15rpx;text-overflow:ellipsis;white-space:nowrap}.capacity{font-size:15rpx;font-weight:750}.capacity strong{color:#f44358;font-size:22rpx}.capacity text{margin-left:5rpx;font-size:23rpx}.state-card{margin-top:22rpx;padding:60rpx 30rpx;text-align:center;border:3rpx solid var(--ink);border-radius:26rpx;background:#fff;box-shadow:0 9rpx 0 rgba(17,24,39,.12)}.state-icon{display:flex;align-items:center;justify-content:center;width:92rpx;height:92rpx;margin:auto;border:3rpx solid var(--ink);border-radius:29rpx;background:#ffdf35;box-shadow:0 7rpx 0 var(--ink);font-size:36rpx;font-weight:950}.state-title{margin-top:24rpx;font-size:27rpx;font-weight:950}.state-copy{margin-top:8rpx;color:#707987;font-size:19rpx;line-height:1.55}.state-card button{height:64rpx;margin-top:21rpx;border:2rpx solid var(--ink);border-radius:999rpx;background:#22dd9c;font-size:18rpx;font-weight:950;line-height:60rpx}.state-card.error .state-icon{background:#ff7787}.loading-list .activity-card{height:235rpx}.safe-space{height:160rpx}.floating-create{position:fixed;z-index:20;right:24rpx;bottom:calc(24rpx + env(safe-area-inset-bottom));height:78rpx;padding:0 27rpx;border:3rpx solid var(--ink);border-radius:999rpx;background:#ff5d70;color:var(--ink);font-size:21rpx;font-weight:950;line-height:72rpx;box-shadow:0 8rpx 0 var(--ink)}.floating-create text{font-size:28rpx}@media screen and (min-width:768px){.page{width:750rpx;margin:auto}.floating-create{right:calc(50% - 351rpx)}}
.page{background:radial-gradient(circle at 92% 0,rgba(55,205,212,.18),transparent 28%),linear-gradient(180deg,#eefaff 0,#f7fbfd 44%,#f4f8fa 100%)!important}.back,.my-link{border:1rpx solid #cfe1e9!important;background:#fff!important;box-shadow:none!important;color:#1475c5}.hero{border:1rpx solid #d7e8ef!important;background:linear-gradient(135deg,#1268c9,#19abc4)!important;box-shadow:0 16rpx 34rpx rgba(29,104,145,.16)!important;color:#fff}.hero-art text{border:0;background:rgba(255,255,255,.18);box-shadow:none;color:#fff}.hero-art view{border:0;background:rgba(255,243,200,.72)}.category{border:1rpx solid #d7e6ed!important;background:#fff!important;box-shadow:none!important}.category.active{border-color:#1778ce!important;background:#1778ce!important;box-shadow:0 7rpx 16rpx rgba(23,120,206,.16)!important}.mode-grid{border:1rpx solid #dce9ef!important;background:#fff!important}.mode-grid view.active{background:#e7f8fb;color:#14758a}.list-head button,.floating-create{border:0!important;box-shadow:0 8rpx 18rpx rgba(8,169,103,.16)!important;background:linear-gradient(135deg,#08a967,#0abca1)!important;color:#fff!important}.list-head button[disabled],.floating-create[disabled]{opacity:.48;box-shadow:none!important}.activity-card,.state-card{border:1rpx solid #dce9ef!important;box-shadow:0 12rpx 30rpx rgba(34,78,103,.075)!important;background:rgba(255,255,255,.97)!important}.activity-image{border-right:1rpx solid #dce9ef!important}.activity-image.fallback{color:#fff}.activity-image.fallback text{border:0;background:rgba(255,255,255,.75);box-shadow:none;color:#1475c5}.creator view{border:0;background:#e6f7fb;color:#1475c5}.state-icon{border:0;background:#e8f7fb;color:#1477c7;box-shadow:none}.state-card button{border:1rpx solid #b9dbe5!important;background:#fff!important;color:#1475c5!important;box-shadow:none!important}.loading-list .activity-card{background:linear-gradient(100deg,#e6f1f5 30%,#f8fcfd 45%,#e6f1f5 60%)!important;background-size:220% 100%;animation:community-activity-shimmer 1.2s ease-in-out infinite}@keyframes community-activity-shimmer{0%{background-position:100% 0}100%{background-position:-100% 0}}
.floating-create{bottom:calc(154rpx + env(safe-area-inset-bottom))!important}
